// Run once for all items. Reads the three upstream Supabase fetches by name.
function normDomain(d) {
  if (!d) return '';
  return String(d).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim();
}
function hostOf(url) {
  try { return normDomain(new URL(url).host); } catch { return normDomain(url); }
}
function urlMatchesDomain(url, domain) {
  if (!url || !domain) return false;
  const h = hostOf(url);
  return h === domain || h.endsWith('.' + domain);
}
function textIncludes(text, needle) {
  if (!text || !needle) return false;
  return String(text).toLowerCase().includes(String(needle).toLowerCase());
}

const queries = $('Get active queries').all().map((i) => i.json || {});
const competitors = $('Get competitors').all().map((i) => i.json || {});
const checks = $('Get recent checks').all().map((i) => i.json || {});

// competitors grouped by the entity they belong to
const compByEntity = {};
for (const c of competitors) {
  if (!c.entity_id) continue;
  (compByEntity[c.entity_id] = compByEntity[c.entity_id] || []).push(c);
}

// latest visibility_checks row per (query_id, platform)
const latest = {};
for (const ch of checks) {
  const k = ch.query_id + '\u0000' + ch.platform;
  const prev = latest[k];
  if (!prev || new Date(ch.run_at).getTime() > new Date(prev.run_at).getTime()) latest[k] = ch;
}

const gaps = [];
for (const q of queries) {
  const comps = compByEntity[q.entity_id] || [];
  if (comps.length === 0) continue; // nothing to compare against
  for (const key of Object.keys(latest)) {
    const ch = latest[key];
    if (ch.query_id !== q.id) continue;
    // we only record a gap when WE are not mentioned on this row
    if (ch.mentioned !== false) continue;
    const urls = Array.isArray(ch.source_urls) ? ch.source_urls : [];
    const snippet = ch.snippet || '';
    for (const comp of comps) {
      const dom = normDomain(comp.domain);
      const inUrls = urls.some((u) => urlMatchesDomain(u, dom));
      const inSnippet = textIncludes(snippet, dom) || textIncludes(snippet, comp.name);
      if (!inUrls && !inSnippet) continue;
      const where = inUrls ? 'cited in sources' : 'named in the answer';
      gaps.push({
        json: {
          query_id: q.id,
          platform: ch.platform,
          competitor_id: comp.id,
          note: comp.name + ' ' + where + ' for "' + q.query_text + '" on ' + ch.platform + '; we are not mentioned',
        },
      });
    }
  }
}

return gaps;
